// --- atf_comp.FDb.ind_sortline.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool atf_comp::ind_sortline_InsertMaybe(atf_comp::FSortline& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_sortline_next == (atf_comp::FSortline*)-1)) {// check if in hash already
        row.ind_sortline_hashval = algo::Smallstr50_Hash(0, row.sortline);
        ind_sortline_Reserve(1);
        u32 index = row.ind_sortline_hashval & (_db.ind_sortline_buckets_n - 1);
        atf_comp::FSortline* *prev = &_db.ind_sortline_buckets_elems[index];
        do {
            atf_comp::FSortline* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).sortline == row.sortline) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_sortline_next;
        } while (true);
        if (retval) {
            row.ind_sortline_next = *prev;
            _db.ind_sortline_n++;
            *prev = &row;
        }
    }
    return retval;
}

