// --- atf_comp.TableId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool atf_comp::value_SetStrptrMaybe(atf_comp::TableId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 11: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','t','f','d','b','.','T','f'): {
                    if (memcmp(rhs.elems+8,"ilt",3)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_Tfilt); ret = true; break; }
                    break;
                }
                case LE_STR8('a','t','f','d','b','.','t','f'): {
                    if (memcmp(rhs.elems+8,"ilt",3)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_tfilt); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 13: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','t','f','d','b','.','T','e'): {
                    if (memcmp(rhs.elems+8,"stenv",5)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_Testenv); ret = true; break; }
                    break;
                }
                case LE_STR8('a','t','f','d','b','.','t','e'): {
                    if (memcmp(rhs.elems+8,"stenv",5)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_testenv); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 14: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','t','f','d','b','.','S','o'): {
                    if (memcmp(rhs.elems+8,"rtline",6)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_Sortline); ret = true; break; }
                    break;
                }
                case LE_STR8('a','t','f','d','b','.','s','o'): {
                    if (memcmp(rhs.elems+8,"rtline",6)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_sortline); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 18: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','t','f','d','b','.','U','n'): {
                    if (memcmp(rhs.elems+8,"stableattr",10)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_Unstableattr); ret = true; break; }
                    if (memcmp(rhs.elems+8,"stableline",10)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_Unstableline); ret = true; break; }
                    break;
                }
                case LE_STR8('a','t','f','d','b','.','u','n'): {
                    if (memcmp(rhs.elems+8,"stableattr",10)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_unstableattr); ret = true; break; }
                    if (memcmp(rhs.elems+8,"stableline",10)==0) { value_SetEnum(parent,atf_comp_TableId_atfdb_unstableline); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

